DO $$ BEGIN IF (SELECT count(*) FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND exception_class='pre_anchor_blocking') > 0 THEN RAISE EXCEPTION 'pre_anchor_blocking'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."users" AS "users" WHERE email IS NOT NULL AND btrim(email) = '') THEN RAISE EXCEPTION 'pre_anchor_blocking:users.email_canonical_nonblank'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."users" AS "users" WHERE email_canonical IS NOT NULL AND EXISTS (SELECT 1 FROM users duplicate WHERE duplicate.email_canonical = users.email_canonical AND duplicate.id <> users.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:users.email_canonical_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."users" AS "users" WHERE phone_number IS NOT NULL AND btrim(phone_number) <> '' AND (CASE WHEN phone_number IS NULL OR btrim(phone_number)='' THEN NULL WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ELSE NULL END) IS NULL) THEN RAISE EXCEPTION 'pre_anchor_blocking:users.phone_canonical_source_valid'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."users" AS "users" WHERE (CASE WHEN users.phone_number IS NULL OR btrim(users.phone_number)='' THEN NULL WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ELSE NULL END) IS NOT NULL AND EXISTS (SELECT 1 FROM users duplicate WHERE (CASE WHEN duplicate.phone_number IS NULL OR btrim(duplicate.phone_number)='' THEN NULL WHEN regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(duplicate.phone_number,''),'[^0-9]','','g') ELSE NULL END) = (CASE WHEN users.phone_number IS NULL OR btrim(users.phone_number)='' THEN NULL WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(users.phone_number,''),'[^0-9]','','g') ELSE NULL END) AND duplicate.id <> users.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:users.phone_canonical_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."users" AS "users" WHERE birthday_type IS NOT NULL AND birthday_type NOT IN ('SOLAR','LUNAR')) THEN RAISE EXCEPTION 'pre_anchor_blocking:users.birthday_type_domain'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."categories" AS "categories" WHERE badge_variant NOT IN ('default','secondary','destructive','outline')) THEN RAISE EXCEPTION 'pre_anchor_blocking:categories.badge_variant_domain'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."categories" AS "categories" WHERE sort_order < 0) THEN RAISE EXCEPTION 'pre_anchor_blocking:categories.sort_order_nonnegative'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."alumni_database" AS "alumni_database" WHERE mobile IS NOT NULL AND btrim(mobile) <> '' AND (CASE WHEN mobile IS NULL OR btrim(mobile)='' THEN NULL WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(mobile,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(mobile,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ELSE NULL END) IS NULL) THEN RAISE EXCEPTION 'pre_anchor_blocking:alumni_database.mobile_canonical_source_valid'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."alumni_database" AS "alumni_database" WHERE (CASE WHEN alumni_database.mobile IS NULL OR btrim(alumni_database.mobile)='' THEN NULL WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ELSE NULL END) IS NOT NULL AND EXISTS (SELECT 1 FROM alumni_database duplicate WHERE (CASE WHEN duplicate.mobile IS NULL OR btrim(duplicate.mobile)='' THEN NULL WHEN regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(duplicate.mobile,''),'[^0-9]','','g') ELSE NULL END) = (CASE WHEN alumni_database.mobile IS NULL OR btrim(alumni_database.mobile)='' THEN NULL WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(alumni_database.mobile,''),'[^0-9]','','g') ELSE NULL END) AND duplicate.id <> alumni_database.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:alumni_database.mobile_canonical_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."alumni_database" AS "alumni_database" WHERE matched_user_id IS NOT NULL AND EXISTS (SELECT 1 FROM alumni_database duplicate WHERE duplicate.matched_user_id = alumni_database.matched_user_id AND duplicate.id <> alumni_database.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:alumni_database.matched_user_id_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."community_events" AS "community_events" WHERE legacy_obituary_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM obituaries WHERE obituaries.id = community_events.legacy_obituary_id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:community_events.legacy_obituary_fk'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."community_events" AS "community_events" WHERE event_type NOT IN ('obituary','wedding','opening','other')) THEN RAISE EXCEPTION 'pre_anchor_blocking:community_events.event_type_domain'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."community_events" AS "community_events" WHERE status NOT IN ('draft','published')) THEN RAISE EXCEPTION 'pre_anchor_blocking:community_events.status_domain'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."event_parse_rate_limits" AS "event_parse_rate_limits" WHERE request_count < 0) THEN RAISE EXCEPTION 'pre_anchor_blocking:event_parse_rate_limits.request_count_nonnegative'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."event_parse_rate_limits" AS "event_parse_rate_limits" WHERE updated_at < window_started_at) THEN RAISE EXCEPTION 'pre_anchor_blocking:event_parse_rate_limits.updated_after_window_start'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."pending_registrations" AS "pending_registrations" WHERE btrim(email) = '') THEN RAISE EXCEPTION 'pre_anchor_blocking:pending_registrations.email_canonical_nonblank'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."pending_registrations" AS "pending_registrations" WHERE status = 'pending' AND EXISTS (SELECT 1 FROM pending_registrations duplicate WHERE duplicate.status = 'pending' AND duplicate.kakao_id = pending_registrations.kakao_id AND duplicate.id <> pending_registrations.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:pending_registrations.pending_kakao_id_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."pending_registrations" AS "pending_registrations" WHERE status = 'pending' AND EXISTS (SELECT 1 FROM pending_registrations duplicate WHERE duplicate.status = 'pending' AND duplicate.email_canonical = pending_registrations.email_canonical AND duplicate.id <> pending_registrations.id)) THEN RAISE EXCEPTION 'pre_anchor_blocking:pending_registrations.pending_email_canonical_unique'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."pending_registrations" AS "pending_registrations" WHERE status IS NULL) THEN RAISE EXCEPTION 'pre_anchor_blocking:pending_registrations.status_null'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."pending_registrations" AS "pending_registrations" WHERE status IS NOT NULL AND status NOT IN ('pending','approved','rejected')) THEN RAISE EXCEPTION 'pre_anchor_blocking:pending_registrations.status_domain'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public."kakao_oauth_states" AS "kakao_oauth_states" WHERE expires_at <= started_at) THEN RAISE EXCEPTION 'pre_anchor_blocking:kakao_oauth_states.expiry_after_start'; END IF; END $$;
ALTER TABLE public.users DROP COLUMN phone_canonical;
ALTER TABLE public.users ADD COLUMN phone_canonical text GENERATED ALWAYS AS (CASE WHEN phone_number IS NULL OR btrim(phone_number)='' THEN NULL WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(phone_number,''),'[^0-9]','','g') ELSE NULL END) STORED;
ALTER TABLE public.alumni_database DROP COLUMN mobile_canonical;
ALTER TABLE public.alumni_database ADD COLUMN mobile_canonical text GENERATED ALWAYS AS (CASE WHEN mobile IS NULL OR btrim(mobile)='' THEN NULL WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^8210[0-9]{8}$' THEN '0'||substring(regexp_replace(coalesce(mobile,''),'[^0-9]','','g') from 3) WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^10[0-9]{8}$' THEN '0'||regexp_replace(coalesce(mobile,''),'[^0-9]','','g') WHEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ~ '^0[0-9]{9,10}$' THEN regexp_replace(coalesce(mobile,''),'[^0-9]','','g') ELSE NULL END) STORED;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__birthday_type_domain__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__birthday_type_domain__check" CHECK ((birthday_type IS NULL OR birthday_type IN ('SOLAR','LUNAR'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__email_canonical_nonblank__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__email_canonical_nonblank__check" CHECK ((email IS NULL OR btrim(email)<>'')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__phone_canonical_format__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__phone_canonical_format__check" CHECK ((phone_canonical IS NULL OR phone_canonical ~ '^[0-9]{10,11}$')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users__phone_canonical_source_valid__check') THEN ALTER TABLE public."users" ADD CONSTRAINT "users__phone_canonical_source_valid__check" CHECK ((phone_number IS NULL OR btrim(phone_number)='' OR phone_canonical IS NOT NULL)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='categories__badge_variant_domain__check') THEN ALTER TABLE public."categories" ADD CONSTRAINT "categories__badge_variant_domain__check" CHECK ((badge_variant IN ('default','secondary','destructive','outline'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='categories__sort_order_nonnegative__check') THEN ALTER TABLE public."categories" ADD CONSTRAINT "categories__sort_order_nonnegative__check" CHECK ((sort_order >= 0)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='alumni_database__mobile_canonical_format__check') THEN ALTER TABLE public."alumni_database" ADD CONSTRAINT "alumni_database__mobile_canonical_format__check" CHECK ((mobile_canonical IS NULL OR mobile_canonical ~ '^[0-9]{10,11}$')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='alumni_database__mobile_canonical_source_valid__check') THEN ALTER TABLE public."alumni_database" ADD CONSTRAINT "alumni_database__mobile_canonical_source_valid__check" CHECK ((mobile IS NULL OR btrim(mobile)='' OR mobile_canonical IS NOT NULL)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_events__event_type_domain__check') THEN ALTER TABLE public."community_events" ADD CONSTRAINT "community_events__event_type_domain__check" CHECK ((event_type IN ('obituary','wedding','opening','other'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_events__status_domain__check') THEN ALTER TABLE public."community_events" ADD CONSTRAINT "community_events__status_domain__check" CHECK ((status IN ('draft','published'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='event_parse_rate_limits__request_count_nonnegative__check') THEN ALTER TABLE public."event_parse_rate_limits" ADD CONSTRAINT "event_parse_rate_limits__request_count_nonnegative__check" CHECK ((request_count >= 0)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='event_parse_rate_limits__updated_after_window_start__check') THEN ALTER TABLE public."event_parse_rate_limits" ADD CONSTRAINT "event_parse_rate_limits__updated_after_window_start__check" CHECK ((updated_at >= window_started_at)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='pending_registrations__email_canonical_nonblank__check') THEN ALTER TABLE public."pending_registrations" ADD CONSTRAINT "pending_registrations__email_canonical_nonblank__check" CHECK ((btrim(email)<>'')); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='pending_registrations__status_domain__check') THEN ALTER TABLE public."pending_registrations" ADD CONSTRAINT "pending_registrations__status_domain__check" CHECK ((status IN ('pending','approved','rejected'))); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='kakao_oauth_states__expiry_after_start__check') THEN ALTER TABLE public."kakao_oauth_states" ADD CONSTRAINT "kakao_oauth_states__expiry_after_start__check" CHECK ((expires_at > started_at)); END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__amount_positive__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__amount_positive__check" CHECK ((amount > 0)) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.amount_positive') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__amount_positive__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__status_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__status_domain__check" CHECK ((status IN ('pending','completed','failed'))) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.status_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__status_domain__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__type_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__type_domain__check" CHECK ((type IN ('연회비','기타'))) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.type_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__type_domain__check"; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='payments__year_domain__check') THEN ALTER TABLE public.payments ADD CONSTRAINT "payments__year_domain__check" CHECK ((year BETWEEN 2024 AND 2100)) NOT VALID; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.schema_data_exceptions WHERE version=1 AND status='open' AND rule_code='payments.year_domain') THEN ALTER TABLE public.payments VALIDATE CONSTRAINT "payments__year_domain__check"; END IF; END $$;
